  "inlineSchema": "// Watchtower data model\n// Prisma schema — the agent's memory: every invoice it watches, every\n// reminder it sent, every fee it applied, and the proof (audit trail).\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// A business that connected their Stripe account to Watchtower\nmodel Account {\n  id              String   @id @default(cuid())\n  stripeAccountId String   @unique // the connected Stripe account id (acct_...)\n  email           String\n  businessName    String?\n  passwordHash    String? // set on first login; null before setup\n  createdAt       DateTime @default(now())\n\n  invoices  Invoice[]\n  clients   Client[]\n  fees      FeePolicy[]\n  settings  Settings?\n  templates InvoiceTemplate[]\n}\n\n// A customer of the business (mirrored from Stripe)\nmodel Client {\n  id               String   @id @default(cuid())\n  accountId        String\n  account          Account  @relation(fields: [accountId], references: [id])\n  stripeCustomerId String   @unique\n  name             String\n  email            String?\n  createdAt        DateTime @default(now())\n\n  invoices Invoice[]\n}\n\n// The fee terms the business owner set at invoice creation\nmodel FeePolicy {\n  id        String   @id @default(cuid())\n  accountId String\n  account   Account  @relation(fields: [accountId], references: [id])\n  // \"flat\" | \"percent\" | \"none\"\n  kind      String\n  // flat: dollars; percent: 0-100\n  amount    Float\n  // days after due date before the fee applies\n  graceDays Int      @default(7)\n  createdAt DateTime @default(now())\n\n  invoice Invoice?\n}\n\n// One invoice Watchtower is watching\nmodel Invoice {\n  id               String     @id @default(cuid())\n  accountId        String\n  account          Account    @relation(fields: [accountId], references: [id])\n  clientId         String?\n  client           Client?    @relation(fields: [clientId], references: [id])\n  stripeInvoiceId  String     @unique\n  stripeNumber     String? // human-facing invoice number (e.g. HUDSON-0007)\n  hostedInvoiceUrl String? // the real Stripe payment link for the client\n  amount           Int // cents\n  currency         String     @default(\"usd\")\n  dueDate          DateTime\n  status           String     @default(\"open\") // open | paid | void | uncollectible\n  feePolicyId      String?    @unique\n  feePolicy        FeePolicy? @relation(fields: [feePolicyId], references: [id])\n  feeApplied       Boolean    @default(false)\n  feeInvoiceId     String? // the stripe invoice id of the late-fee invoice\n  feeAmountCents   Int? // the late-fee amount in cents (mirrors the fee invoice)\n  feeIssuedAt      DateTime? // when the fee invoice was created\n  feeDueDate       DateTime? // the fee invoice's own due date\n  feeStatus        String? // \"open\" | \"paid\" (null = no fee on this invoice)\n  feePaidAt        DateTime? // when the fee invoice was paid\n  paidAt           DateTime?\n  repliedAt        DateTime? // when the client replied — pauses reminders\n  escalateAction   String? // null | \"send_reminder\" | \"owner_calling\" — owner's decision at escalation\n  waiveNote        String? // owner's reason for waiving the late fee\n  createdAt        DateTime   @default(now())\n  updatedAt        DateTime?  @updatedAt\n\n  reminders Reminder[]\n  replies   Reply[]\n  auditLog  AuditEvent[]\n}\n\n// A client's reply to a reminder, captured via inbound email.\n// Reply-to addresses are per-invoice (reply-<invoiceId>@domain), so the\n// inbound webhook matches the reply to exactly one invoice.\nmodel Reply {\n  id        String   @id @default(cuid())\n  invoiceId String\n  invoice   Invoice  @relation(fields: [invoiceId], references: [id])\n  from      String\n  subject   String\n  body      String\n  createdAt DateTime @default(now())\n}\n\n// Every reminder email the agent sent (the proof)\nmodel Reminder {\n  id        String   @id @default(cuid())\n  invoiceId String\n  invoice   Invoice  @relation(fields: [invoiceId], references: [id])\n  step      String // \"t-7\" | \"t-3\" | \"due\" | \"t+3\" | \"t+7\" | \"t+14\"\n  sentAt    DateTime @default(now())\n  subject   String\n  messageId String? // Resend message id\n}\n\n// The audit trail — everything the agent did, in order\nmodel AuditEvent {\n  id        String   @id @default(cuid())\n  invoiceId String\n  invoice   Invoice  @relation(fields: [invoiceId], references: [id])\n  event     String // \"invoice_created\" | \"reminder_sent\" | \"fee_applied\" | \"invoice_paid\" ...\n  detail    String?\n  createdAt DateTime @default(now())\n}\n\n// Per-account preferences\nmodel Settings {\n  id               String   @id @default(cuid())\n  accountId        String   @unique\n  account          Account  @relation(fields: [accountId], references: [id])\n  // email timing offsets (days before/after due date)\n  remindT7         Boolean  @default(true)\n  remindT3         Boolean  @default(true)\n  remindDue        Boolean  @default(true)\n  remindT3late     Boolean  @default(true)\n  remindT7late     Boolean  @default(true)\n  remindT14        Boolean  @default(true)\n  // auto-apply fees after the first approval?\n  autoApplyFees    Boolean  @default(false)\n  // the owner's inbox — where client replies are forwarded and alerts go.\n  // Falls back to the Stripe account email when unset.\n  ownerEmail       String?\n  // Alert toggles (owner email notifications)\n  alertFeeApproval Boolean  @default(true) // a late fee needs my approval\n  alertOverdue     Boolean  @default(true) // an invoice goes overdue\n  alertPayment     Boolean  @default(false) // a client pays\n  createdAt        DateTime @default(now())\n}\n\n// A recurring invoice template: set it once, Dunn auto-creates on schedule.\nmodel InvoiceTemplate {\n  id            String    @id @default(cuid())\n  accountId     String\n  account       Account   @relation(fields: [accountId], references: [id])\n  clientName    String\n  clientEmail   String\n  amount        Int // cents\n  currency      String    @default(\"usd\")\n  dueDays       Int       @default(30) // days from today for the due date\n  // Fee settings (denormalized — copied to each created invoice's FeePolicy)\n  feeKind       String    @default(\"none\") // \"flat\" | \"percent\" | \"none\"\n  feeAmount     Float     @default(0)\n  graceDays     Int       @default(7)\n  // Schedule\n  frequency     String    @default(\"monthly\") // \"monthly\" | \"weekly\" | \"biweekly\" | \"custom\"\n  customDay     Int? // day of month for \"custom\" frequency (1-28)\n  nextRunDate   DateTime // next date to create the invoice\n  // Status\n  active        Boolean   @default(true)\n  lastRunAt     DateTime?\n  lastRunOk     Boolean? // whether the last run succeeded\n  lastError     String? // last error message if the run failed\n  sentCount     Int       @default(0) // total invoices created from this template\n  lastInvoiceId String? // the most recent invoice created from this template\n  createdAt     DateTime  @default(now())\n  updatedAt     DateTime  @updatedAt\n}\n",
